package com.careerpilot.modules.assessment.controller;
import com.careerpilot.modules.assessment.dto.*;import com.careerpilot.modules.assessment.service.AssessmentService;import com.careerpilot.security.CurrentUser;import io.swagger.v3.oas.annotations.Operation;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/assessments")
public class AssessmentController{private final AssessmentService service;public AssessmentController(AssessmentService service){this.service=service;}@GetMapping@Operation(summary="List active assessments",description="Answer keys are never included.")public List<AssessmentSummaryResponse>list(){return service.catalog();}@GetMapping("/{id}")@Operation(summary="Get an assessment",description="Options are returned without correctness or explanations.")public AssessmentDetailResponse get(@PathVariable UUID id){return service.detail(id);}@PostMapping("/{id}/attempts")@ResponseStatus(HttpStatus.CREATED)@Operation(summary="Start an immutable assessment attempt")public AttemptResponse start(@PathVariable UUID id){return service.start(CurrentUser.require(),id);}}
